#include <string>
#include <numeric>
using namespace std;

class Solution {
public:
    long long concatenateAndMultiply(long long n) {
        string s = to_string(n);
        string non_zero = "";
        long long sum_digits = 0;
        for (char c : s) {
            sum_digits += (c - '0');
            if (c != '0') non_zero += c;
        }
        long long C = non_zero.empty() ? 0 : stoll(non_zero);
        return C * sum_digits;
    }
};

class Solution {
    public long concatenateAndMultiply(long n) {
        String s = Long.toString(n);
        StringBuilder nonZero = new StringBuilder();
        long sum = 0;
        for (char c : s.toCharArray()) {
            sum += (c - '0');
            if (c != '0') nonZero.append(c);
        }
        long C = nonZero.length() == 0 ? 0 : Long.parseLong(nonZero.toString());
        return C * sum;
    }
}

var concatenateAndMultiply = function(n) {
    const s = String(n);
    let sum = 0n;
    let nonZero = "";
    for (const c of s) {
        sum += BigInt(c);
        if (c !== '0') nonZero += c;
    }
    const C = nonZero.length === 0 ? 0n : BigInt(nonZero);
    return Number(C * sum);
};
